SET TIME ZONE 'UTC';
WITH m AS (SELECT generate_series(DATE '2023-01-01',DATE '2025-12-01','1 month')::date mes),x AS (SELECT m.mes,coalesce(sum(v.receita_mercadoria_pre_devolucao) FILTER(WHERE v.elegivel),0) receita FROM m LEFT JOIN pedidos p ON date_trunc('month',p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date=m.mes LEFT JOIN vw_itens_venda v USING(pedido_id) GROUP BY 1),y AS (SELECT *,lag(receita,12) over(order by mes) receita_ano_anterior FROM x) SELECT *,receita-receita_ano_anterior variacao_abs,100*(receita-receita_ano_anterior)/nullif(receita_ano_anterior,0) taxa_variacao_pct FROM y ORDER BY mes;
